# Turning a discovered prompt list into slash commands
async def build_slash_commands(session):
    response = await session.list_prompts()
    commands = {}
    for prompt in response.prompts:
        commands["/" + prompt.name] = {
            "description": prompt.description,
            "arguments": prompt.arguments,
        }
    return commands

// User types: /summarize_pull_request pr_number=482 tone=short
function parseSlashCommand(input, commandDefs) {
  const [name, ...rest] = input.slice(1).split(' ');
  const def = commandDefs['/' + name];
  const args = {};
  for (const pair of rest) {
    const [key, value] = pair.split('=');
    args[key] = value;
  }
  for (const arg of def.arguments) {
    if (arg.required && !(arg.name in args)) {
      throw new Error('Missing required argument: ' + arg.name);
    }
  }
  return { name, args };
}

